pub struct ReferenceAudio {
    /// 库内文件名 (`ref_<hash>.wav`)
    pub file: String,
    /// 内容哈希 (前 16 位)
    pub hash: String,
    /// 时长 (秒)
    pub duration: f64,
    /// 采样率
    pub sample_rate: u32,
    /// 参考文本 (GSOV 在使用 vocoder 的 v3/v4 上要求非空, 且须与音频逐字一致)
    pub text: String,
    /// 语言码
    pub language: LanguageCode,
    /// 风格标签
    pub tags: Vec<StyleTag>,
    /// 添加时间 (Unix 毫秒)
    pub created_at: i64,
}

